def superusers_become_owners(apps, schema_editor):
    """Accounts created with `createsuperuser` before roles existed become OWNERs."""
    User = apps.get_model("accounts", "User")
    User.objects.filter(is_superuser=True).update(role="OWNER", is_staff=True)
    User.objects.exclude(role="OWNER").update(is_staff=False, is_superuser=False)


